      const page = createElementFromHTML('<main class="page-shell"></main>');
      page.appendChild(SupportHero());
      page.appendChild(SupportForm());
      return page;
    }

    function App() {
      return SupportPage();
    }

    document.getElementById("root").appendChild(App());
  </script>
